package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;
public class PhysicalCopyActivity extends FinseqActivity{
 int policyId;public void onCreate(Bundle b){super.onCreate(b);policyId=getIntent().getIntExtra("policy_id",0);if(policyId<=0){finish();return;}LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"Physical Copy / Duplicate Tools");LinearLayout body=Ui.contentColumn(this);root.addView(body);LinearLayout card=Ui.card(this);card.addView(Ui.text(this,"Policy #"+policyId,18,true));card.addView(Ui.sub(this,"Use this screen when Admin identifies a duplicate policy from Policy Details."));Button preview=Ui.greenButton(this,"Preview Physical PDF");preview.setOnClickListener(v->startActivity(new Intent(this,PdfPreviewActivity.class).putExtra("policy_id",policyId)));card.addView(preview);Button share=Ui.button(this,"Share Policy Link");share.setOnClickListener(v->share());card.addView(share);Button del=Ui.redButton(this,"Delete Duplicate Policy");del.setOnClickListener(v->confirmDelete());card.addView(del);body.addView(card);setContentView(Ui.scroll(this,root));}
 void share(){PolicySharing.whatsapp(this,policyId,false);}
 void confirmDelete(){final EditText confirm=Ui.input(this,"Type DELETE");new AlertDialog.Builder(this).setTitle("Delete duplicate policy?").setMessage("Only use this after confirming the record is duplicate. This action removes the policy record and its linked physical-copy entry.").setView(confirm).setPositiveButton("Delete",(d,w)->{if(!"DELETE".equals(confirm.getText().toString().trim())){Ui.toast(this,"Type DELETE to confirm");return;}deleteNow();}).setNegativeButton("Cancel",null).show();}
 void deleteNow(){Ui.run(this,()->{try{JSONObject r=ApiClient.post(this,"/api/v3/policies/"+policyId+"/delete",new JSONObject().put("confirm","DELETE"));Ui.ui(this,()->{Ui.toast(this,r.optString("message","Duplicate policy deleted"));finish();});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
